import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate, conversion_rate_by_group, conversions_in_window,
    longest_conversion_streak, pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_none_counts_as_a_nonconversion():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_last_duplicate_wins_before_sorting():
    old = {"id": "b", "day": 5, "converted": False}
    new = {"id": "b", "day": 3, "converted": True}
    early = {"id": "z", "day": 1, "converted": False}
    tied = {"id": "a", "day": 3, "converted": False}
    assert dedupe_sessions([old, tied, new, early]) == [early, tied, new]


def test_parser_skips_comments_and_trims_fields():
    assert parse_session_log(["", "  ", "  # comment", " x , 3 , 0 ", "y,4, "]) == [
        {"id": "x", "day": 3, "converted": False},
        {"id": "y", "day": 4, "converted": None},
    ]


@pytest.mark.parametrize('bad_line', ['x,3', 'x,3,1,extra', 'x,today,0'])
def test_parser_counts_skipped_lines_in_errors(bad_line):
    with pytest.raises(ValueError, match=r'line 4\b'):
        parse_session_log(['', '# comment', 'a,1,1', bad_line])


def test_daily_range_and_window():
    events = parse_session_log(['a,1,1', 'b,2,1', 'c,2,1', 'd,3,0', 'e,5,1', 'f,6,1'])
    counts = daily_conversion_counts(events, 2, 5)
    assert counts == [2, 0, 0, 1]
    assert daily_conversion_counts(events, 5, 2) == []
    assert conversions_in_window(counts, 3) == 1
    assert conversions_in_window(counts, 0) == 0
    assert conversions_in_window(counts, 10) == 3


def test_campaign_summary_uses_all_sessions_and_calendar_days():
    groups = {'one': parse_session_log(['a,1,1']), 'two': parse_session_log(['b,3,1', 'c,5,0']), 'empty': []}
    assert pooled_conversion_rate(groups) == 2 / 3
    assert campaign_summary(groups, 2) == {'rate': 0.667, 'recent': 0, 'groups': 2}
    assert campaign_summary({'empty': []}, 2) == {'rate': 0.0, 'recent': 0, 'groups': 0}


def test_group_ordering_and_empty_groups():
    groups = {'z': [{'converted': True}], 'empty': [], 'a': [{'converted': True}], 'b': [{'converted': False}]}
    assert top_converting_groups(groups, 5) == ['a', 'z', 'b']
    assert top_converting_groups(groups, 1) == ['a']
    assert list(conversion_rate_by_group(groups).items()) == [('a', 1.0), ('b', 0.0), ('empty', None), ('z', 1.0)]


def test_streak_resets_on_nonpositive_counts():
    assert longest_conversion_streak([1, 0, 2, 1, -1, 3]) == 2
    assert longest_conversion_streak([]) == 0
